#!/usr/bin/env python3
"""Build Western Cape CA(SA) Talent Atlas from Maps people.jsonl + supplementary verified records.
Re-runnable. Research date 2026-10-14. Never fabricates LinkedIn/designation/location.
Primary = designation CONFIRMED + location_confidence CONFIRMED (repo) or equivalent explicit evidence (supplementary).
HIGH location -> PROBABLE_WESTERN_CAPE -> verification queue. HIGH_CONFIDENCE designation -> queue.
"""
import csv, json, re, collections, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
BASE = ROOT/"markets/accountants"; OUT = BASE/"western-cape-atlas"; DATE="2026-10-14"
OUT.mkdir(parents=True, exist_ok=True); (OUT/"import-package").mkdir(exist_ok=True)

def load_jsonl(p): return [json.loads(l) for l in open(p) if l.strip()]
people=load_jsonl(BASE/"people.jsonl"); companies=load_jsonl(BASE/"companies.jsonl"); sources=load_jsonl(BASE/"sources.jsonl")
comp_by_name={c['company_name'].lower():c for c in companies}
MUNI={"Cape Town":"City of Cape Town","City of Cape Town":"City of Cape Town","Milnerton (Cape Town)":"City of Cape Town","City of Cape Town / Paarl":"City of Cape Town / Drakenstein (unresolved)","Stellenbosch":"Stellenbosch","Somerset West":"City of Cape Town","Durbanville":"City of Cape Town","Paarl":"Drakenstein","Ladismith":"Kannaland","Saldanha Bay Local Municipality":"Saldanha Bay","George":"George","Franschhoek":"Stellenbosch"}
def split_name(n):
    p=n.split(); return p[0], " ".join(p[1:]) if len(p)>1 else ""
def seniority(t):
    t=(t or "").lower()
    if any(k in t for k in ["chief financial officer","cfo","group chief"]): return "CFO / Group CFO"
    if any(k in t for k in ["partner","managing director","chief executive","ceo","founder","principal","sole practitioner"]): return "Partner" if "partner" in t else "CEO / Managing Director / Founder"
    if any(k in t for k in ["financial director","finance director","director","executive director"]): return "Director"
    if any(k in t for k in ["head of","head -","head "]): return "Head of Function"
    if "senior manager" in t: return "Senior Manager"
    if "manager" in t: return "Manager"
    if any(k in t for k in ["faculty","lecturer","professor"]): return "Academic / Other"
    if any(k in t for k in ["specialist","lead"]): return "Senior Accountant / Senior Specialist"
    if any(k in t for k in ["financial accountant","accountant"]): return "Accountant / Specialist"
    if any(k in t for k in ["fractional","consultan","executive leader"]): return "Independent Consultant"
    return "Executive" if "executive" in t else "Other"
def industry_map(ind):
    m={"Accounting / Audit":"Professional Services","Government":"Public Sector","Building Materials":"Construction & Materials","Quarrying / Aggregates":"Construction & Materials","Oil & Gas":"Energy & Renewables"}
    return m.get(ind, ind or "")
