 dict(candidate_id="WC26-0002",first_name="Iain",last_name="Duthie",full_name="Iain Duthie",current_title="Branch Manager (Cape Town)",current_employer="Fenns Incorporated",city="Cape Town",designation_status="CONFIRMED",location_status="CONFIRMED_WESTERN_CAPE",linkedin_profile_url="",linkedin_match_status="NOT_FOUND",linkedin_match_score="",industry_primary="Professional Services",function_primary="Tax",seniority_level="Manager",award_or_recognition="",award_year="",discovery_channel="G — Accounting firm team page",primary_source_url="https://www.fenns.co.za/chartered-accountants-cape-town/",additional_source_urls="",designation_evidence_url="https://www.fenns.co.za/chartered-accountants-cape-town/",location_evidence_url="https://www.fenns.co.za/chartered-accountants-cape-town/",employment_evidence_url="https://www.fenns.co.za/chartered-accountants-cape-town/",notes="Firm states: 'Iain is a Chartered Accountant (SA)' and names him Cape Town Branch Manager, overseeing tax consulting and financial statement preparation."),
