 dict(candidate_id="WC26-0004",first_name="Henry",last_name="Whitehead",full_name="Henry Whitehead",current_title="Director",current_employer="Smith & Associates Inc.",city="Stellenbosch",designation_status="CONFIRMED",location_status="CONFIRMED_WESTERN_CAPE",linkedin_profile_url="",linkedin_match_status="NOT_FOUND",linkedin_match_score="",industry_primary="Professional Services",function_primary="Audit and Assurance",seniority_level="Director",award_or_recognition="",award_year="",discovery_channel="G — Accounting firm board page",primary_source_url="https://smith1.co.za/team/board-of-directors/",additional_source_urls="",designation_evidence_url="https://smith1.co.za/team/board-of-directors/",location_evidence_url="https://smith1.co.za/team/board-of-directors/",employment_evidence_url="https://smith1.co.za/team/board-of-directors/",notes="Firm states qualified Chartered Accountant, SAICA Chartered Accountant (SA) + IRBA Registered Auditor; articles at LDP 2005; firm based Stellenbosch."),
